import json
def task_func(url: str, output_path: str) -> list:
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")

    try:
        if url.startswith(('http://', 'https://')):
            response = requests.get(url, verify=False)
            response.raise_for_status()
            text = response.text
        else:
            with open(url, 'r') as file:
                text = file.read()
    except requests.RequestException as e:
        raise ValueError(f"Error fetching the content: {e}") from e
    except IOError as e:
        raise IOError(f"Error reading the file: {e}") from e

    phone_numbers = re.findall(r'\b\d{3}[-.\s]?\d{3}[-.\s]?\d{4}\b', text)

    with open(output_path, 'w') as json_file:
        json.dump(phone_numbers, json_file)

    return phone_numbers

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range provided.")

    active_ips = []

    for ip in network.hosts():
        try:
            response = requests.get(f"http://{ip}", timeout=timeout)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

